  "user_query": "I need to stop by a professor's office on the 3rd floor and then find a large lecture room on the 1st floor that holds at least 70 students.",
  "targets": [
    {
      "order": 0,
      "intent": "navigation_query",
      "target_type": "implicit",
      "filter": "parentName LIKE '%3rd Floor%'",
      "semantics": "professor's office, 3rd floor",
      "source": "LLM"
