    {
      "order": 1,
      "intent": "navigation_query",
      "target_type": "implicit",
      "filter": "parentName LIKE '%1st Floor%' AND capacity >= 70",
      "semantics": "large lecture room, 1st floor, holds at least 70 students",
      "source": "LLM"
    }
  ],
  "extraction_method": "llm"
}

